WITH res AS (SELECT p.object_id AS id, CAST(json_extract_string(p.state,'$.date') AS DATE) AS day, CASE WHEN json_extract_string(p.state,'$.side') = 'debit' THEN CAST(json_extract(p.state,'$.amount') AS BIGINT) ELSE -CAST(json_extract(p.state,'$.amount') AS BIGINT) END AS b FROM objects p JOIN objects a ON json_extract_string(p.state,'$.account') = a.object_id WHERE p.object_type = 'posting' AND a.object_type = 'account' AND COALESCE(json_extract_string(p.state,'$.book'), 'main') = 'pl-stat' AND json_extract_string(a.state,'$.type') IN ('revenue', 'expense')), acc AS (SELECT object_id, json_extract_string(state,'$.code') AS code FROM objects WHERE object_type = 'account'), post AS (SELECT json_extract_string(p.state,'$.account') AS account, CASE WHEN json_extract_string(p.state,'$.side') = 'debit' THEN CAST(json_extract(p.state,'$.amount') AS BIGINT) ELSE -CAST(json_extract(p.state,'$.amount') AS BIGINT) END AS signed FROM objects p WHERE p.object_type = 'posting' AND COALESCE(json_extract_string(p.state,'$.book'), 'main') = 'pl-stat'), bank AS (SELECT a.object_id AS id, COALESCE(SUM(p.signed), 0) AS bal, COUNT(p.signed) AS n FROM acc a LEFT JOIN post p ON p.account = a.object_id WHERE a.code = '130' GROUP BY a.object_id), openinv AS (SELECT object_id, object_type, CAST(json_extract(state,'$.open') AS BIGINT) AS open FROM objects WHERE object_type IN ('sales_invoice', 'purchase_invoice') AND CAST(COALESCE(json_extract(state,'$.open'), '0') AS BIGINT) > 0), vat AS (SELECT object_id, json_extract_string(state,'$.period') AS period, CAST(json_extract(state,'$.vat_due') AS BIGINT) AS due FROM objects WHERE object_type = 'vat_settlement' ORDER BY period DESC LIMIT 1), cit AS (SELECT object_id, json_extract_string(state,'$.period') AS period, CAST(json_extract(state,'$.advance') AS BIGINT) AS due FROM objects WHERE object_type = 'cit_advance' ORDER BY period DESC LIMIT 1), counted AS (SELECT object_id, object_type, json_extract_string(state,'$.status') AS status, json_extract_string(state,'$.settlement_status') AS sstatus FROM objects WHERE object_type IN ('ksef_submission', 'bank_operation', 'matching_difference', 'period_lock')), rmk AS (SELECT COALESCE(SUM(CASE WHEN json_extract_string(p.state,'$.side') = 'debit' THEN CAST(json_extract(p.state,'$.amount') AS BIGINT) ELSE -CAST(json_extract(p.state,'$.amount') AS BIGINT) END), 0) AS bal, (SELECT COUNT(*) FROM objects WHERE object_type = 'prepaid_cost' AND json_extract_string(state,'$.status') = 'active') AS n, (SELECT string_agg(object_id, ',' ORDER BY object_id) FROM objects WHERE object_type = 'prepaid_cost' AND json_extract_string(state,'$.status') = 'active') AS o FROM acc a JOIN objects p ON p.object_type = 'posting' AND json_extract_string(p.state,'$.account') = a.object_id AND COALESCE(json_extract_string(p.state,'$.book'), 'main') = 'pl-stat' WHERE a.code = '640') SELECT key, label, amount, count, note, o AS _of FROM (SELECT -1 AS k, 'result_month' AS key, 'Wynik w tym miesiącu' AS label, -COALESCE(SUM(b) FILTER (WHERE day >= CAST(date_trunc('month', {{today}}) AS DATE) AND day <= {{today}}), 0) AS amount, NULL AS count, strftime({{today}}, '%Y-%m') || ', przed opodatkowaniem' AS note, string_agg(id, ',' ORDER BY id) FILTER (WHERE day >= CAST(date_trunc('month', {{today}}) AS DATE) AND day <= {{today}}) AS o FROM res UNION ALL SELECT 0, 'result_year', 'Wynik od początku roku', -COALESCE(SUM(b) FILTER (WHERE year(day) = year({{today}}) AND day <= {{today}}), 0), NULL, strftime({{today}}, '%Y') || ', przed opodatkowaniem', string_agg(id, ',' ORDER BY id) FILTER (WHERE year(day) = year({{today}}) AND day <= {{today}}) FROM res UNION ALL SELECT 1, 'bank', 'Na rachunku bieżącym', bal, n, 'zapisów od początku roku', id FROM bank UNION ALL SELECT 2, 'receivables', 'Należności', COALESCE(SUM(open), 0), COUNT(*), 'otwartych faktur sprzedaży', string_agg(object_id, ',' ORDER BY object_id) FROM openinv WHERE object_type = 'sales_invoice' UNION ALL SELECT 3, 'payables', 'Dla dostawców', COALESCE(SUM(open), 0), COUNT(*), 'faktur zakupu do zapłaty', string_agg(object_id, ',' ORDER BY object_id) FROM openinv WHERE object_type = 'purchase_invoice' UNION ALL SELECT 3.2, 'prepaid', 'Koszty rozliczane w czasie (RMK)', bal, n, 'zostało do rozliczenia', o FROM rmk WHERE n > 0 OR bal <> 0 UNION ALL SELECT 3.5, 'cit_due', 'Zaliczka na CIT', due, NULL, period, object_id FROM cit UNION ALL SELECT 4, 'vat_due', 'VAT do zapłaty', due, NULL, period, object_id FROM vat UNION ALL SELECT 5, 'ksef', 'Faktury przyjęte w KSeF', NULL, COUNT(*), NULL, string_agg(object_id, ',' ORDER BY object_id) FROM counted WHERE object_type = 'ksef_submission' AND status = 'accepted' UNION ALL SELECT 6, 'bank_lines', 'Pozycje wyciągu przeczytane', NULL, COUNT(*), NULL, string_agg(object_id, ',' ORDER BY object_id) FROM counted WHERE object_type = 'bank_operation' UNION ALL SELECT 7, 'settled', 'Pozycje wyciągu rozliczone', NULL, COUNT(*), NULL, string_agg(object_id, ',' ORDER BY object_id) FROM counted WHERE object_type = 'bank_operation' AND sstatus = 'settled' UNION ALL SELECT 8, 'differences', 'Różnice groszowe zamknięte w tolerancji', NULL, COUNT(*), NULL, string_agg(object_id, ',' ORDER BY object_id) FROM counted WHERE object_type = 'matching_difference' UNION ALL SELECT 9, 'closed', 'Zamknięte miesiące', NULL, COUNT(*), NULL, string_agg(object_id, ',' ORDER BY object_id) FROM counted WHERE object_type = 'period_lock') ORDER BY k
